def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find contiguous, same-color bars along each edge.
    def runs(line, fixed, horizontal):
        result = []
        i = 0
        while i < len(line):
            color = line[i]
            if color == bg:
                i += 1
                continue
            j = i + 1
            while j < len(line) and line[j] == color:
                j += 1
            if j - i >= 2:
                result.append((color, i, j - 1, fixed, horizontal))
            i = j
        return result

    bars = []
    bars += runs(grid[0], 0, True)
    bars += runs(grid[h - 1], h - 1, True)
    bars += runs([grid[r][0] for r in range(h)], 0, False)
    bars += runs([grid[r][w - 1] for r in range(h)], w - 1, False)

    pairs = []
    for a in bars:
        for b in bars:
            if a is b or a[0] != b[0] or a[4] != b[4]:
                continue
            if a[4] and {a[3], b[3]} == {0, h - 1}:
                pass
            elif not a[4] and {a[3], b[3]} == {0, w - 1}:
                pass
            else:
                continue
            if a[2] - a[1] != b[2] - b[1]:
                continue
            if a[3] < b[3]:
                pairs.append((a, b))
    if not pairs:
        return out

    bar1, bar2 = max(pairs, key=lambda p: p[0][2] - p[0][1])
    horizontal = bar1[4]
    lo1, hi1, edge1 = bar1[1], bar1[2], bar1[3]
    lo2, hi2, edge2 = bar2[1], bar2[2], bar2[3]
    bar_color = bar1[0]
    fill_colors = {bg, bar_color}

    # Every non-background, non-bar cell in the interior is a line marker.
    markers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or grid[r][c] == bar_color:
                continue
            if horizontal:
                if c < lo1 or c > hi1:
                    continue
                idx = c - lo1
                coord1 = c
                coord2 = lo2 + idx
                source_edge = edge1 if edge1 in (0, h - 1) else edge2
                if source_edge == edge1:
                    fixed_source, fixed_other = edge1, edge2
                else:
                    fixed_source, fixed_other = edge2, edge1
                markers.append((r, c, grid[r][c], coord1, coord2,
                                fixed_source, fixed_other))
            else:
                if r < lo1 or r > hi1:
                    continue
                idx = r - lo1
                coord1 = r
                coord2 = lo2 + idx
                source_edge = edge1 if edge1 in (0, w - 1) else edge2
                if source_edge == edge1:
                    fixed_source, fixed_other = edge1, edge2
                else:
                    fixed_source, fixed_other = edge2, edge1
                markers.append((r, c, grid[r][c], coord1, coord2,
                                fixed_source, fixed_other))

    for r, c, color, coord1, coord2, source_edge, other_edge in markers:
        fill_colors.add(color)
        out[r][c] = 4
        if horizontal:
            # Draw from the source edge toward the marker.
            step = 1 if source_edge == 0 else -1
            rr = source_edge + step
            while 0 <= rr < h and rr != r:
                out[rr][c] = color
                rr += step
            # Continue the corresponding line across the span from the other bar.
            step = 1 if other_edge == 0 else -1
            rr = other_edge + step
            while 0 <= rr < h and rr != (h - 1 if other_edge == 0 else 0):
                out[rr][coord2] = color
                rr += step
        else:
            step = 1 if source_edge == 0 else -1
            cc = source_edge + step
            while 0 <= cc < w and cc != c:
                out[r][cc] = color
                cc += step
            step = 1 if other_edge == 0 else -1
            cc = other_edge + step
            while 0 <= cc < w and cc != (w - 1 if other_edge == 0 else 0):
                out[coord2][cc] = color
                cc += step

    return out
